using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Globalization;
using System.Text.RegularExpressions;
using System.Collections.Generic;
namespace Musikbox {
 public static class LibrarySearch {
  public static string Normalize(string value){var b=new StringBuilder();foreach(char c in (value??"").Normalize(NormalizationForm.FormKD))if(CharUnicodeInfo.GetUnicodeCategory(c)!=UnicodeCategory.NonSpacingMark)b.Append(Char.ToLowerInvariant(c));return b.ToString().Replace("ß","ss");}
  public static string Compact(string value){return Regex.Replace(Normalize(value),"[^a-z0-9]","");}
  public static string Correct(string value){return Regex.Replace(value??"",@"\b(?:lenny|lenni|lennie|leni|lainie|laine|lane|laney|leiny)\s+wilson\b","Lainey Wilson",RegexOptions.IgnoreCase);}
  public static string Sound(string value){string s=Compact(value).Replace("ph","f").Replace("ck","k").Replace("sch","sh").Replace("tz","z");s=Regex.Replace(s,@"([a-z])\1+","$1");s=Regex.Replace(s,"c(?=[aouklr])","k");s=Regex.Replace(s,"ow(?=er)","au");s=Regex.Replace(s,"ai|ay|ey|ei","e").Replace("ie","i").Replace("w","v");return Regex.Replace(s,"y$","i");}
  public static bool Near(string a,string b,int limit){if(Math.Abs(a.Length-b.Length)>limit)return false;var previous=Enumerable.Range(0,b.Length+1).ToArray();for(int i=1;i<=a.Length;i++){var next=new int[b.Length+1];next[0]=i;int min=i;for(int j=1;j<=b.Length;j++){next[j]=Math.Min(Math.Min(previous[j]+1,next[j-1]+1),previous[j-1]+(a[i-1]==b[j-1]?0:1));min=Math.Min(min,next[j]);}if(min>limit)return false;previous=next;}return previous[b.Length]<=limit;}
  public static bool Matches(Song song,string folder,string query){if(String.IsNullOrWhiteSpace(query))return true;var fields=new[]{song.Artist,song.Title,song.Album,song.Year,song.Genre,song.Comment,Path.GetFileName(song.Source),folder??""};var normalized=fields.Select(Normalize).ToArray();var compact=fields.Select(Compact).ToArray();var words=fields.SelectMany(f=>Regex.Split(Normalize(f),"[^a-z0-9]+")).Where(x=>x.Length>0).Select(Sound).ToArray();foreach(string term in Regex.Split(Normalize(Correct(query)),@"[\s.,!?;:]+")){string needle=Compact(term);if(needle.Length==0)continue;if(normalized.Any(f=>f.Contains(term))||compact.Any(f=>f.Contains(needle)))continue;if(needle.Length<4||needle.All(Char.IsDigit))return false;string sound=Sound(needle);if(!words.Any(w=>w.Length>=3&&(w==sound||Near(w,sound,needle.Length>=8?2:1))))return false;}return true;}
  static string[] Words(string value){return SearchText.Meaningful(Correct(value));}
  static double Token(string a,string b){string x=Sound(a),y=Sound(b);if(x.Length==0||y.Length==0)return 0;if(x==y)return 1;if(x.Length>=3&&y.Length>=3&&(x.Contains(y)||y.Contains(x)))return .88;if(x.All(Char.IsDigit)||y.All(Char.IsDigit))return 0;if(Math.Min(x.Length,y.Length)>=4&&Near(x,y,Math.Max(x.Length,y.Length)>=8?2:1))return .76;return 0;}
  sealed class Score {public Song Song;public double Value,Coverage;public int Matched;}
  static Score Rank(Song song,string spoken){spoken=Regex.Replace(spoken,@"(?:vier|four|4)\s*(?:mal|x|by|bei)\s*(?:vier|four|4)\s*(?:mal|x|by|bei)\s*(?:u|you)","4x4xu",RegexOptions.IgnoreCase);var wanted=Words(spoken);var artist=Words(song.Artist);var title=Words(song.Title);double total=0;int matched=0,ah=0,th=0;foreach(var word in wanted){double best=0;bool isArtist=false;foreach(var a in artist){double n=Token(word,a);if(n>best){best=n;isArtist=true;}}foreach(var t in title){double n=Token(word,t);if(n>best){best=n;isArtist=false;}}total+=best;if(best>=.7){matched++;if(isArtist)ah++;else th++;}}double coverage=wanted.Length==0?0:total/wanted.Length;return new Score{Song=song,Value=coverage*.88+(ah>0&&th>0?.08:0)+Math.Min(1,matched/(double)Math.Max(1,artist.Length+title.Length))*.04,Coverage=coverage,Matched=matched};}
  public static bool VoiceMatches(Song song,string query){string spoken=Sound(VoiceTerm(query));if(spoken.Length>=5&&new[]{song.Artist,song.Title}.Select(Sound).Any(name=>name==spoken||(name.Length>=5&&Near(name,spoken,Math.Max(name.Length,spoken.Length)>=8?2:1))))return true;return Matches(song,"",VoiceTerm(query))||Rank(song,VoiceTerm(query)).Coverage>=.74;}
  public static Song FindVoice(IEnumerable<Song> songs,IEnumerable<string> phrases){var alternatives=phrases.ToArray();if(alternatives.Length==0)return null;var ranked=songs.Select(s=>alternatives.Select(p=>Rank(s,p)).OrderByDescending(x=>x.Value).First()).OrderByDescending(x=>x.Value).ThenByDescending(x=>x.Matched).ToArray();if(ranked.Length==0||ranked[0].Value<.73||ranked[0].Coverage<.78)return null;if(ranked.Length>1&&ranked[1].Value>=ranked[0].Value-.055&&ranked[1].Matched>=ranked[0].Matched)return null;return ranked[0].Song;}
  public static string VoiceTerm(string text){bool play;string term=PlayTerm(text,out play);term=Regex.Replace(term,@"^(?:bitte\s+)?(?:suche(?:\s+nach)?|such(?:e)?\s+mir|finde|find|search(?:\s+for)?|alle\s+(?:titel|lieder|songs)(?:\s+von)?|all\s+(?:songs|tracks)(?:\s+by)?)\s+","",RegexOptions.IgnoreCase);term=Regex.Replace(term,@"(?:vier|four|4)\s*(?:mal|x|by|bei)\s*(?:vier|four|4)\s*(?:mal|x|by|bei)\s*(?:u|you)","4x4xU",RegexOptions.IgnoreCase);return Regex.Replace(term,@"\s+(?:von|by)\s+"," ",RegexOptions.IgnoreCase).Trim();}
  public static string VoiceQuery(IEnumerable<Song> songs,IEnumerable<string> alternatives){var library=songs.ToArray();var terms=alternatives.Select(VoiceTerm).Where(t=>!String.IsNullOrWhiteSpace(t)).Distinct().ToArray();var exact=terms.Select(t=>new{Term=t,Count=library.Count(s=>Matches(s,"",t)),Words=Regex.Split(t,@"\s+").Length}).Where(t=>t.Count>0).OrderByDescending(t=>t.Words).ThenBy(t=>t.Count).FirstOrDefault();if(exact!=null)return exact.Term;var found=FindVoice(library,terms);return found==null?terms.FirstOrDefault()??"":found.Title+" "+found.Artist;}
  public static string PlayTerm(string text,out bool play){var match=Regex.Match((text??"").Trim(),@"^(?:bitte\s+)?(?:spiele|spiel|play|starte|start)\s+(?:mir\s+)?(?:den\s+(?:titel|song)\s+|das\s+lied\s+|von\s+)?(.+)$",RegexOptions.IgnoreCase);play=match.Success;return Correct((play?match.Groups[1].Value:text??"").Trim().TrimEnd('.','!','?',',',';',':'));}
 }
}
